CREATE TABLE IF NOT EXISTS event_inbox (id text PRIMARY KEY, trail_id text NOT NULL, event jsonb NOT NULL, received_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS trail_projection (id text PRIMARY KEY, state text NOT NULL, trail jsonb NOT NULL, journal_head text);
CREATE TABLE IF NOT EXISTS operation_ledger (key text PRIMARY KEY, plan_digest text NOT NULL, status text NOT NULL, result jsonb, at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS outbox (id text PRIMARY KEY, trail_id text NOT NULL, event jsonb NOT NULL, trail jsonb NOT NULL, effects jsonb NOT NULL, published_at timestamptz);
CREATE TABLE IF NOT EXISTS runner_leases (id text PRIMARY KEY, trail_id text NOT NULL, lease jsonb NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS approvals (id text PRIMARY KEY, trail_id text NOT NULL, bound jsonb NOT NULL, decision jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS usage_ledger (id text PRIMARY KEY, trail_id text NOT NULL, usage jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS audit_events (sequence bigserial PRIMARY KEY, id text UNIQUE NOT NULL, row_data jsonb NOT NULL, prev_hash text NOT NULL, hash text NOT NULL);
CREATE TABLE IF NOT EXISTS signals (id text PRIMARY KEY, fingerprint text UNIQUE NOT NULL, signal jsonb NOT NULL, muted_until timestamptz);
CREATE TABLE IF NOT EXISTS inbox_items (id text PRIMARY KEY, trail_id text NOT NULL, item jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS reconciliation (operation_key text PRIMARY KEY, note text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
